import media from "./media.json";

// Generated by `npm run media` from the raw Drive folders (see scripts/process-media.mjs).
export type Media =
  | { type: "image"; src: string; width: number; height: number }
  | { type: "video"; src: string; poster: string; width: number; height: number };
const mediaFor = (id: string) => ((media as Record<string, Media[]>)[id] ?? []) as Media[];

